mapper.select:
SELECT REVEAL.ID id, REVIEW.REVIEW_TG_STATUS reviewTgStatus, REVIEW.REVIEW_TG_TIME reviewTgTime, F3.REAL_NAME reviewTgUser, REVIEW.REVIEW_STATUS reviewStatus, REVIEW.REVIEW_TIME reviewTime, F2.REAL_NAME reviewUser, REVEAL.REP_ID repId, REVEAL.PRODID prodid, decode( R1.REP_PROD_TYPE, '03', R2.PROD_NAME, decode(R1.PROD_NAME, null, REVEAL.PROD_NAME, R1.PROD_NAME) ) prodName, REVEAL.REPORT_CATEGORY reportCategory, rfp.NAME reportCategoryName, REVEAL.REPORT_NAME reportName, case when REVEAL.START_DATE is null or REVEAL.START_DATE = REVEAL.END_DATE then to_char(REVEAL.END_DATE, 'yyyy-mm-dd') else to_char(REVEAL.START_DATE, 'yyyy-mm-dd') || '--' || to_char(REVEAL.END_DATE, 'yyyy-mm-dd') end reportDate, to_char(REVEAL.REVEAL_END_DATE, 'yyyy-mm-dd hh24:mi') revealEndDateStr, REVEAL.END_DATE endDate, REVEAL.START_DATE startDate, nvl(REVEAL.FILENAME, REVEAL.SYS_FILENAME) confirmFileName, nvl(REVEAL.FILEPATH, REVEAL.SYS_FILEPATH) confirmFilePath, to_char(REVEAL.CREATE_TIME, 'yyyy-mm-dd hh24:mi') createTimeStr, to_char(REVEAL.CONFIRM_DATE, 'yyyy-mm-dd hh24:mi') confirmDateStr, decode( REVEAL.CONFIRM_STATUS, '1', nvl(F1.REAL_NAME, '系统自动确认'), null ) confirmUser, REVEAL.IS_CONFIRM isConfirm, REVEAL.ANNEX annex, REVEAL.ANNEX_PATH annexPath, REVEAL.CREATE_USER createUser, REVEAL.CREATE_DEPT createDept, REVEAL.CREATE_TIME createTime, REVEAL.UPDATE_USER updateUser, REVEAL.UPDATE_TIME updateTime FROM REP_REVEAL REVEAL inner join REP_REVEAL_REVIEW REVIEW on REVEAL.ID = REVIEW.REVEAL_ID and REVIEW.REVIEW_STATUS='03' inner join REP_REVIEW_GROUP rrg on REVIEW.REVIEW_TG_GROUP=rrg.GROUP_ID and rrg.USER_NAME = #{loginUser} left join REP_PROD_INFO R1 on REVEAL.PRODID = R1.PROD_ID left join REP_PROD_INFO R2 on R1.P_PROD_ID = R2.PROD_ID left join (SELECT * FROM( SELECT ROW_NUMBER()over(PARTITION by su.USER_NAME,su.REAL_NAME ORDER BY su.USER_NAME DESC) as ronum,su.USER_NAME,su.REAL_NAME FROM SYS_USER su ) F where F.ronum = 1) F1 on REVEAL.CONFIRM_USER = F1.USER_NAME left join (SELECT * FROM( SELECT ROW_NUMBER()over(PARTITION by su.USER_NAME,su.REAL_NAME ORDER BY su.USER_NAME DESC) as ronum,su.USER_NAME,su.REAL_NAME FROM SYS_USER su ) F where F.ronum = 1) F2 on REVIEW.REVIEW_USER = F2.USER_NAME left join (SELECT * FROM( SELECT ROW_NUMBER()over(PARTITION by su.USER_NAME,su.REAL_NAME ORDER BY su.USER_NAME DESC) as ronum,su.USER_NAME,su.REAL_NAME FROM SYS_USER su ) F where F.ronum = 1) F3 on REVIEW.REVIEW_TG_USER = F3.USER_NAME left join rep_ftp_path rfp on REVEAL.REPORT_CATEGORY = rfp.ID where 1=1 and REVEAL.status ='E'
AND REVEAL.PRODID IN
#{item}
AND REVEAL.PRODID IN
#{item}
AND REVEAL.REPORT_CATEGORY IN
#{item}
AND REVEAL.REPORT_NAME =#{reportName,jdbcType=VARCHAR}
AND REVEAL.REPORT_CATEGORY IN
#{item}
AND REVIEW.REVIEW_TG_STATUS IN
#{item}
AND REVIEW.REVIEW_TG_USER IN
#{item}
AND to_char(REVIEW.REVIEW_TG_TIME,'yyyy-mm-dd') >= #{reviewTgTimeStart,jdbcType=VARCHAR}
AND to_char(REVIEW.REVIEW_TG_TIME,'yyyy-mm-dd') <= #{reviewTgTimeEnd,jdbcType=VARCHAR}
AND ((to_char(REVEAL.END_DATE,'yyyy-mm-dd') >= #{reportDateStart,jdbcType=VARCHAR} and REVEAL.START_DATE is null and to_char(REVEAL.END_DATE,'yyyy-mm-dd') <= #{reportDateEnd,jdbcType=VARCHAR} ) or( to_char(REVEAL.START_DATE,'yyyy-mm-dd') >= #{reportDateStart,jdbcType=VARCHAR} and to_char(REVEAL.END_DATE,'yyyy-mm-dd') <= #{reportDateEnd,jdbcType=VARCHAR} ) )
order by REVIEW.REVIEW_TG_STATUS asc ,REVIEW.UPDATE_TIME desc
